svg.script:

(function() {
  const svg = document.getElementById('p12-svg-root');

  const btnCortical = document.getElementById('p12-btn-cortical');
  const btnSubcortical = document.getElementById('p12-btn-subcortical');

  const panelCortical = document.getElementById('p12-panel-content-cortical');
  const panelSubcortical = document.getElementById('p12-panel-content-subcortical');

  function setMode(mode) {
    svg.setAttribute('data-active', mode);

    if (mode === 'cortical') {
      panelCortical.style.display = 'block';
      panelSubcortical.style.display = 'none';
    } else {
      panelCortical.style.display = 'none';
      panelSubcortical.style.display = 'block';
    }
  }

  // Eventos de Clique
  btnCortical.addEventListener('click', function() { setMode('cortical'); });
  btnSubcortical.addEventListener('click', function() { setMode('subcortical'); });

  document.getElementById('p12-hotspot-cortical').addEventListener('click', function() { setMode('cortical'); });
  document.getElementById('p12-hotspot-subcortical').addEventListener('click', function() { setMode('subcortical'); });

  // Teclado para Acessibilidade
  const interactiveElements = [
    btnCortical,
    btnSubcortical,
    document.getElementById('p12-hotspot-cortical'),
    document.getElementById('p12-hotspot-subcortical')
  ];

  interactiveElements.forEach(el => {
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        el.click();
      }
    });
  });
})();
